import {coordinateProfile} from './coordinates.js?v=28';
import {timeCaption} from './workspace.js?v=17';
import {themeFor,paths,coreParams,usableParams} from './learning.js?v=17';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function homeMarkup(experiments,prefs,{search,grade,topic,filter,pathFilter},icon){
 const topics=[...new Set(experiments.map(e=>e.topic))];
 const done=Object.values(prefs.progress||{}).filter(p=>p?.every(Boolean)).length;
 const recent=(prefs.recent||[]).map(id=>experiments.find(e=>e.id===id)).find(Boolean);
 const resume=recent||experiments.find(e=>e.id==='uniform');
 return `<div class="home">
 <section class="main-banner orbital-banner cinematic-banner" aria-labelledby="bannerTitle">
  <div class="banner-art"><img class="cinematic-poster" src="video/black-hole.webp" width="1920" height="1080" alt="" aria-hidden="true" fetchpriority="high"><div id="bannerCanvas" class="banner-viewport"><span class="banner-loading" role="status">Đang mở không gian…</span></div></div>
  <div class="banner-topline"><span>PHÒNG THÍ NGHIỆM VẬT LÍ</span><span>LỚP 10 — 12</span></div>
  <div class="banner-copy"><h1 id="bannerTitle" class="primary-heading">Thí nghiệm<br><em>Vật lí.</em></h1><p>Điều chỉnh thông số. Đo và kiểm chứng.</p><div class="banner-actions"><a class="button primary" href="#library">Chọn thí nghiệm <span aria-hidden="true">↗</span></a><a class="banner-resume" href="#lab/${resume.id}">${recent?'Tiếp tục bài gần nhất':'Bắt đầu với chuyển động'} <span aria-hidden="true">→</span></a></div></div>
  <button data-action="banner-fullscreen" class="banner-expand" aria-label="Xem banner toàn màn hình" title="Toàn màn hình">⛶</button>
 </section>
 <div class="banner-model-links" aria-label="Mở nhanh thí nghiệm"><span>Thí nghiệm gợi ý</span><a href="#lab/pendulum">Con lắc <span aria-hidden="true">↗</span></a><a href="#lab/ohm">Mạch điện <span aria-hidden="true">↗</span></a><a href="#lab/prism">Lăng kính <span aria-hidden="true">↗</span></a></div>
 <section class="entry-grid" aria-label="Lựa chọn nhanh"><div class="start-here"><h2>Bắt đầu từ đây</h2><div class="class-entry">${[10,11,12].map((g,i)=>`<button data-grade="${g}" data-goto-library="true" style="--entry-color:${['#245acb','#247b65','#7952a8'][i]}"><span>Lớp <strong>${g}</strong></span><small>${['Cơ học & năng lượng','Điện trường & sóng','Điện từ & vật lí hiện đại'][i]}</small><b aria-hidden="true">→</b></button>`).join('')}</div></div><div class="continue-entry"><div class="entry-heading"><h2>Tiếp tục khám phá</h2><button data-action="progress" aria-label="Xem sổ tiến độ${done?`, ${done} bài đã khảo sát`:''}">Tiến độ ↗</button></div><a class="recent-entry" href="#lab/${resume.id}"><span aria-hidden="true">↻</span><div><b>${esc(resume.shortTitle)}</b><small>Lớp ${resume.grade} · ${esc(resume.topic)}</small></div><b aria-hidden="true">→</b></a></div></section>
 <section id="library" aria-labelledby="libraryTitle">
 <div class="library-heading"><h2 id="libraryTitle" class="primary-heading">Thư viện thí nghiệm <span>${experiments.length}</span></h2><div class="search">${icon('search')}<label class="sr-only" for="search">Tìm thí nghiệm</label><input id="search" type="search" placeholder="Tìm hiện tượng, dụng cụ, chủ đề…" value="${esc(search)}" aria-describedby="searchHint"><button data-action="clear-search" class="search-clear" aria-label="Xóa từ khóa" hidden>×</button><kbd id="searchHint" title="Phím tắt tìm kiếm">/</kbd></div></div>
 <div class="topic-chips" aria-label="Chủ đề"><button data-topic="all" class="${topic==='all'?'selected':''}" aria-pressed="${topic==='all'}">Tất cả chủ đề</button>${topics.map(t=>{const c=themeFor({topic:t});return `<button data-topic="${t}" style="--accent:${c.color};--soft:${c.soft}" class="${t===topic?'selected':''}" aria-pressed="${t===topic}"><i aria-hidden="true"></i>${t}</button>`}).join('')}</div>
 <div class="catalog-toolbar"><div class="filters"><div class="grade-filters">${['all',10,11,12].map(g=>`<button data-grade="${g}" class="${String(g)===String(grade)?'selected':''}" aria-pressed="${String(g)===String(grade)}">${g==='all'?'Mọi lớp':`Lớp ${g}`}</button>`).join('')}</div><button class="favorite-filter ${filter==='favorites'?'selected':''}" data-action="favorites-home">${icon('star')}Đã lưu</button><button data-action="recent-home" class="${filter==='recent'?'selected':''}">Gần đây</button></div><div class="catalog-options"><label><span class="sr-only">Mức độ</span><select id="levelFilter" aria-label="Mức độ"><option value="all">Mọi mức độ</option><option value="core">Nền tảng THPT</option><option value="extra">Mở rộng</option></select></label><label><span class="sr-only">Sắp xếp</span><select id="catalogSort" aria-label="Sắp xếp"><option value="default">Theo lộ trình</option><option value="name">Tên A → Z</option><option value="grade">Theo lớp</option></select></label></div></div>
 <div id="activeFilters" class="active-filters" aria-label="Bộ lọc đang dùng" hidden></div><div class="catalog-results"><span id="resultCount" role="status" aria-live="polite" aria-atomic="true"></span><button data-action="clear-filters" class="quiet-button" hidden>Bỏ lọc</button></div><div id="cards" class="cards"></div><nav id="pagination" class="pagination" aria-label="Trang thí nghiệm"></nav></section>
 <details class="path-section library-extra"><summary>Tuyến khảo sát <span>Học theo một mạch kiến thức</span></summary><div class="paths">${paths.map((p,i)=>`<button data-path="${i}" class="path-card ${pathFilter===i?'selected':''}" style="--path-color:${p.color}"><span class="path-icon" aria-hidden="true">${p.icon}</span><span><b>${p.title}</b><small>${p.ids.length} thí nghiệm</small></span><span aria-hidden="true">↗</span></button>`).join('')}</div></details>
 <details id="tryExperiment" class="library-extra demo-disclosure"><summary>Thử nhanh trên mô hình <span>Định luật Ohm · Sóng · Quang học</span></summary><section class="hero" aria-label="Bàn thí nghiệm thử nhanh"><div class="hero-stage"><div class="hero-top"><span><i class="hero-dot"></i><b id="heroTitle">Định luật Ohm</b></span><span class="instrument-label">THỬ & QUAN SÁT</span></div><div id="heroCanvas"><div class="render-fallback">Mở bảng để dựng mô hình.</div></div><div id="heroDemo" class="hero-demo"><label>Điện áp <output id="heroVoltageValue">6 V</output><input type="range" id="heroVoltage" min="0" max="12" step=".5" value="6"></label><label>Điện trở<select id="heroResistance"><option value="10">10 Ω</option><option value="20">20 Ω</option><option value="40">40 Ω</option></select></label><div><span>Dòng điện</span><strong id="heroCurrent">0,60 A</strong></div><a class="button primary" id="heroDemoLink" href="#lab/ohm">Mở khảo sát</a></div><div class="hero-bottom"><div class="hero-switch">${[['ohm','Mạch điện'],['interference','Sóng'],['prism','Quang học']].map(([id,t],i)=>`<button data-hero="${id}" class="${i===0?'selected':''}" aria-pressed="${i===0}">${t}</button>`).join('')}</div><span class="float-label">Kéo để xoay mô hình</span><a href="#lab/ohm" id="heroLink" class="hero-launch" aria-label="Mở thí nghiệm đang xem">↗</a></div></div><aside class="hero-research"><span class="eyebrow">CÂU HỎI NHANH</span><h2>Điện áp tăng.<br>Dòng điện đổi thế nào?</h2><p>Giữ điện trở không đổi. Kéo thanh điện áp và đọc ampe kế.</p><a href="#lab/ohm" class="quiet-button">Ghi số liệu trong phòng thí nghiệm →</a></aside></section></details></div>`;
}
export function cardsMarkup(list,prefs,icon){return list.length?list.map(e=>{const c=themeFor(e),done=prefs.progress?.[e.id]?.every(Boolean);return `<article class="experiment-card" style="--accent:${c.color};--soft:${c.soft}"><a href="#lab/${e.id}" class="card-image" data-thumb="${e.id}" aria-label="Mở ${esc(e.shortTitle)}"><div class="thumb-placeholder"><span>${c.icon}</span></div></a><span class="grade-tag">Lớp ${e.grade}${e.extra?' · Mở rộng':' · Nền tảng'}</span><button class="favorite-button ${prefs.favorites.includes(e.id)?'on':''}" data-favorite="${e.id}" aria-pressed="${prefs.favorites.includes(e.id)}" aria-label="Lưu ${esc(e.shortTitle)}">${icon('star')}</button><a href="#lab/${e.id}" class="card-body"><span class="card-topic"><i aria-hidden="true"></i>${e.topic}</span><h3>${e.shortTitle}</h3><p class="card-purpose">${esc(e.description.split(/(?<=[.!?])\s/)[0])}</p><div class="card-bottom"><span>${done?'Đã khảo sát':e.static&&!e.visualOnly||['electric','lever','hooke','magnetic'].includes(e.id)?'Khảo sát theo thông số':'Chạy theo thời gian'}</span><b>↗</b></div></a><button class="preview-button" data-preview="${e.id}" aria-label="Xem trước ${esc(e.shortTitle)}">Xem trước ⤢</button></article>`}).join(''):'<div class="empty"><b>Chưa tìm thấy thí nghiệm phù hợp.</b><button class="button secondary" data-action="clear-filters">Xem tất cả</button></div>';}
export function labMarkup(e,{prefs,state,config,controls,panel,mode,staticMode,experiments=[]},icon){
 const c=themeFor(e),param=coreParams(e)[0];
 return `<div class="lab" data-layout="${mode}" style="--accent:${c.color};--soft:${c.soft}"><div class="lab-breadcrumb"><a class="back" href="#library">← Thư viện</a><span>/ ${e.topic}</span><label class="lab-selector">Đổi thí nghiệm<select id="labSelect" aria-label="Chọn thí nghiệm">${experiments.map(q=>`<option value="${q.id}" ${q.id===e.id?'selected':''}>${esc(q.shortTitle)}</option>`).join('')}</select></label></div><div class="lab-heading"><div><span class="eyebrow">BÀN THÍ NGHIỆM / LỚP ${e.grade}${e.extra?' / MỞ RỘNG':''}</span><h1 tabindex="-1" id="lessonTitle" class="primary-heading">${e.shortTitle}<span class="lesson-icon">${c.icon}</span></h1></div><div class="lab-header-actions"><button class="icon-button ${prefs.favorites.includes(e.id)?'on':''}" data-favorite="${e.id}" aria-label="Lưu thí nghiệm" aria-pressed="${prefs.favorites.includes(e.id)}">${icon('star')}</button><button class="button secondary" data-action="save-session">Lưu phiên ↓</button><button class="icon-button" data-action="reset" aria-label="Đặt lại mô hình; giữ bảng đo">${icon('reset')}</button><button class="icon-button" data-action="focus" aria-label="Bật hoặc tắt chế độ tập trung">${icon('expand')}</button><button class="button primary" data-action="report">Xuất báo cáo ↗</button></div></div><div class="lab-intro"><p>${esc(e.description.split(/(?<=[.!?])\s/)[0])}</p><div class="mode-switch"><button data-mode="explore" class="${mode==='explore'?'selected':''}" aria-pressed="${mode==='explore'}">Khám phá</button><button data-mode="measure" class="${mode==='measure'?'selected':''}" aria-pressed="${mode==='measure'}">Phân tích</button><button data-mode="present" class="${mode==='present'?'selected':''}" aria-pressed="${mode==='present'}">Trình chiếu</button></div></div><div class="workspace-toolbar"><div><button data-action="toggle-controls" aria-controls="controlsPanel" aria-expanded="true">☷ Thông số</button><button data-action="toggle-dock" aria-controls="researchPanel" aria-expanded="true">▥ Dữ liệu & ghi chép <span data-measurement-count class="measurement-count" aria-hidden="true">0</span></button><button data-action="toggle-guidance" aria-controls="guidePanel" aria-pressed="true">ⓘ Hướng dẫn</button></div><div><button data-action="restore-layout">Khôi phục bố cục</button><button data-action="speak-intro" class="present-narration">Nghe hướng dẫn</button><button data-action="exit-present" class="exit-present">← Thoát trình chiếu</button></div></div>${e.id==='electric'?'<div id="electricModeBar" class="electric-modes"></div>':''}
 <div class="workspace"><div class="experiment-work"><div class="instrument-zone"><section class="stage-shell"><div class="stage-top"><span class="live-tag"><i></i><span id="runStatus" role="status">Sẵn sàng</span></span><div class="stage-tools"><div class="projection-switch" role="group" aria-label="Cách biểu diễn mô hình"><button data-projection="3d" aria-pressed="${config.viewMode!=='2d'}" class="${config.viewMode!=='2d'?'selected':''}">3D</button><button data-projection="2d" aria-pressed="${config.viewMode==='2d'}" class="${config.viewMode==='2d'?'selected':''}" title="Hình chiếu vuông góc; giữ nguyên thông số và độ sâu của mô hình">2D</button></div><button data-action="toggle-axes" class="axis-toggle" aria-describedby="coordinateLegend" aria-pressed="${config.switches.axes!==false}" ${coordinateProfile(e.id,state)?'':'hidden'} title="${esc(coordinateProfile(e.id,state)?.note||'')}"><span aria-hidden="true">⌖</span> Trục</button><button data-action="toggle-renderer" title="Đổi chất lượng đồ họa; giữ nguyên góc nhìn 2D hoặc 3D">Đồ họa nhẹ</button><details class="view-menu"><summary>Góc nhìn ⌄</summary><div class="view-menu-options"><button data-camera="iso" aria-label="Góc nhìn phối cảnh" aria-pressed="true">Phối cảnh</button><button data-camera="front" aria-pressed="false">Trước</button><button data-camera="top" aria-pressed="false">Trên</button><button data-action="zoom-in" aria-label="Phóng to">＋</button><button data-action="zoom-out" aria-label="Thu nhỏ">−</button><button data-action="fit-view" class="fit-view">Vừa khung</button></div></details><button class="icon-button" data-action="png" aria-label="Tải ảnh mô hình">${icon('camera')}</button><button class="icon-button" data-action="fullscreen" aria-label="Toàn màn hình">${icon('expand')}</button></div></div><div id="rendererNotice" class="renderer-notice" hidden></div><div class="stage-viewport"><div id="visual" class="visual"><div class="render-fallback" role="status">Đang dựng mô hình…</div></div><div id="sceneTooltip" class="scene-tooltip" hidden></div><button class="touch-interaction" data-action="touch-interaction" aria-pressed="false">Bật tương tác 3D</button><span class="viewport-caption">Kéo nền để xoay · Kéo điểm màu để điều chỉnh</span></div><div id="coordinateLegend" class="coordinate-legend" hidden></div><div id="modelStatus" class="model-status" role="status" aria-live="polite"></div><div id="readouts" class="readouts"></div><div class="transport"><button id="play" data-action="play" class="button primary" ${staticMode?'hidden':''}>${icon('play')}${e.visualOnly?'Phát tia':'Chạy'}</button><button class="icon-button" data-action="step" ${staticMode?'hidden':''} aria-label="Tiến một bước">${icon('step')}</button><div class="time-slider" ${staticMode?'hidden':''}><input type="range" id="time" min="0" max="10" step=".01" value="${state.t||0}" ${staticMode?'disabled':''} aria-label="Thời điểm thí nghiệm"><output id="timeValue"></output></div><select id="speed" aria-label="Tốc độ chạy" ${staticMode?'hidden':''}><option value=".25">0,25×</option><option value=".5">0,5×</option><option value="1" selected>1×</option><option value="2">2×</option></select><span class="static-hint" ${staticMode?'':'hidden'}>Khảo sát theo thông số</span><button class="icon-button loop-toggle" data-action="loop" aria-pressed="${!!config.loop}" aria-label="Bật hoặc tắt lặp lại thí nghiệm" ${staticMode?'hidden':''}>↻</button><button class="button secondary parameters-shortcut" data-action="open-parameters">☷ Thông số</button><button class="button accent" data-action="record">＋ Ghi điểm</button><button class="icon-button" data-action="reset" aria-label="Đặt lại mô hình" title="Đặt lại mô hình; giữ bảng đo">${icon('reset')}</button><button class="icon-button" data-action="toggle-guidance" aria-label="Bật hoặc tắt hướng dẫn" aria-pressed="true">?</button></div><div class="direct-tools"><span class="direct-mark">↔</span><label for="dragKey">Biến tương tác</label><select id="dragKey" aria-label="Thông số điều chỉnh trực tiếp">${usableParams(e,config).map(p=>`<option value="${p.key}" ${(config.dragKey||param?.key)===p.key?'selected':''}>${p.label}</option>`).join('')}</select><button data-action="param-minus" aria-label="Giảm thông số đã chọn">−</button><output id="directValue"></output><button data-action="param-plus" aria-label="Tăng thông số đã chọn">＋</button><button data-action="locate-parameter" class="locate-parameter" aria-label="Mở ô nhập số của biến tương tác">Nhập số ↗</button></div></section><div class="experiment-tools"><button data-action="speak-intro" class="listen-quick">${icon('voice')}Nghe hướng dẫn</button><button data-action="pin">◧ So sánh A/B</button><button data-action="sweep">↔ Quét biến</button><button data-action="share">↗ Thiết lập</button><button data-action="restart-view">⟲ Góc nhìn</button></div><div class="speech-mini" id="speechMini" hidden><output id="speechMiniStatus" role="status" aria-live="polite"></output><button data-action="speech-pause">Tạm dừng</button><button data-action="speech-stop">Dừng đọc</button></div><div id="comparison"></div><details class="guide-disclosure" id="guidePanel"><summary>Hướng dẫn & giọng đọc <span>Thay đổi · Quan sát · Giải thích</span></summary><div class="guide-content"><div class="voice-bar"><button class="listen-guide" data-action="speak-intro">Nghe hướng dẫn</button><button data-action="speak-values">${icon('voice')}Đọc số đo</button><button data-action="speech-pause">Tạm dừng</button><button data-action="speech-stop">Dừng đọc</button>${e.id==='sound'?'<button data-action="tone" id="toneButton">♪ Nghe âm</button>':''}<button data-action="voice-settings" class="voice-settings">Giọng đọc ⚙</button></div><output id="voiceState" class="voice-state" role="status">Hoài My · Tiếng Việt tích hợp</output><div id="coach">${coachMarkup(e,config.guideStep||0)}</div></div></details><div id="selectedState" class="selected-state" hidden></div><div class="model-footnote"><span><i></i>${timeCaption(e)}</span><button data-action="info">Điều kiện mô hình ↗</button></div></div>
 <aside class="research-dock" id="researchPanel" aria-label="Phân tích và ghi chép"><div class="dock-title"><h2>Dữ liệu & ghi chép</h2><button data-action="expand-data" aria-pressed="${!!prefs.layout.dataExpanded}">${prefs.layout.dataExpanded?'Thu chiều rộng':'Mở rộng số liệu'}</button><button data-action="toggle-dock" aria-label="Thu gọn bảng khảo sát">×</button><span>φ / ${e.id.toUpperCase()}</span></div><div class="work-tabs">${[['data','Dữ liệu'],['discover','Đề bài'],['tasks','Sổ tay'],['theory','Mô hình'],['sources','Nguồn']].map(([p,t])=>`<button data-panel="${p}" class="${p===panel?'selected':''}" aria-pressed="${p===panel}">${t}</button>`).join('')}</div><div id="panel"></div></aside></div><div class="resize-handle controls-resizer" role="separator" tabindex="0" data-resize="controlsWidth" aria-orientation="vertical" aria-label="Độ rộng bảng thông số"></div><aside class="controls" id="controlsPanel" aria-label="Thiết lập thí nghiệm">${controls}</aside></div><div class="lab-navigation"><button data-action="previous-lab">← Thí nghiệm trước</button><span>VẬT LÍ LAB / 300 THÍ NGHIỆM</span><button data-action="next-lab">Thí nghiệm tiếp theo →</button></div></div>`;
}
export function discoveryMarkup(e,prefs,stored){const p=prefs.progress?.[e.id]||[false,false,false];return `<section class="discovery-panel"><div class="discovery-prompt"><span class="eyebrow">CÂU HỎI KHẢO SÁT</span><h2>${e.tasks[0]}</h2><label for="prediction">Giả thuyết của bạn</label><input id="prediction" data-notes-for="${e.id}" placeholder="Một dự đoán có thể kiểm tra…" value="${esc(stored?.prediction||'')}"><button class="button secondary" data-action="speak-task">▶ Nghe gợi ý</button></div><div class="investigation-steps">${['Dự đoán','Thao tác & đo','Giải thích'].map((v,i)=>`<label><input type="checkbox" data-progress="${i}" ${p[i]?'checked':''}><span class="step-number">0${i+1}</span><span><b>${v}</b><small>${i===0?'Nêu điều bạn nghĩ sẽ xảy ra':e.tasks[i]}</small></span></label>`).join('')}<p class="progress-note">Tự đánh dấu bước đã làm · lưu trên thiết bị này</p></div></section>`;}

export function coachMarkup(e,step=0){const p=coreParams(e)[0],model=e.learning||{change:`Điều chỉnh ${p.label.toLowerCase()}; giữ các thông số còn lại.`,observe:`Theo dõi mô hình và ba số đọc. ${e.description}`,explain:(e.analysis||e.theory||e.formula).split(/(?<=[.!?])\s/)[0]};const content=[model.change,model.observe,model.explain];return `<section class="learning-coach"><div class="coach-header"><span>HIỂU QUA THAO TÁC</span><div>${['Thay đổi','Quan sát','Giải thích'].map((name,i)=>`<button data-coach="${i}" class="${step===i?'selected':''}" aria-pressed="${step===i}"><b>${i+1}</b>${name}</button>`).join('')}</div></div><p>${esc(content[step]||content[0])}</p><div class="coach-actions">${step===0?'<button data-action="coach-try">Thử một thiết lập ↗</button>':step===1?'<button data-action="coach-record">Ghi kết quả ＋</button>':'<button data-panel="tasks">Viết giải thích →</button>'}<button data-action="speak-coach">◖ Nghe gợi ý</button></div></section>`;}
